use crate::wasi::clocks::wall_clock;

struct Node;

/// Convert days since 1970-01-01 to a (year, month, day) civil date.
/// Howard Hinnant's `civil_from_days` algorithm.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = z - era * 146_097; // [0, 146096]
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32; // [1, 12]
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn format_date(seconds: u64) -> String {
    // 9999-12-31 is day 2_932_896 since the epoch; clamp so the date
    // always renders as exactly ten characters (YYYY-MM-DD).
    const MAX_DAYS: u64 = 2_932_896;
    let days = core::cmp::min(seconds / 86_400, MAX_DAYS) as i64;
    let (y, m, d) = civil_from_days(days);
    let y = y.clamp(0, 9999);
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let date = format_date(now.seconds);
        RunInfo {
            date,
            started: now.seconds,
        }
    }
}

export!(Node);
